insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-ek-193","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Rusting of iron is classified as an electrochemical process because it involves","options":["local anodic oxidation of Fe and cathodic reduction of dissolved oxygen","a purely mechanical wearing away of the metal","melting of iron below 100 °C","photochemical cleavage of Fe–Fe bonds only"],"answer_index":0,"explanation":"Different surface spots act as tiny galvanic cells in the presence of a water film containing O$_2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"},{"id":"che-ek-194","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ordinary rusting of iron requires, besides the metal itself,","options":["both moisture and oxygen","oxygen in a completely dry atmosphere only","a vacuum and ultraviolet light","solid NaCl with no water at all"],"answer_index":0,"explanation":"Water provides the ionic medium; oxygen is the cathodic oxidant. Dry iron in air rusts extremely slowly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"batteries-corrosion"},{"id":"che-ek-195","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"During discharge of a lead storage battery the electrolyte H$_2$SO$_4$ is consumed and the product deposited on both plates is","options":["lead(II) sulphate","lead metal only","lead dioxide only","elemental sulphur"],"answer_index":0,"explanation":"Pb + PbO$_2$ + 2 H$_2$SO$_4$ → 2 PbSO$_4$ + 2 H$_2$O. Charging reverses this reaction and regenerates acid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion"},{"id":"che-ek-196","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The only chemical product of a hydrogen–oxygen fuel cell operating with an alkaline or acid electrolyte is","options":["water","carbon dioxide","ammonia","hydrogen peroxide exclusively"],"answer_index":0,"explanation":"H$_2$ is oxidised and O$_2$ is reduced; their combination yields H$_2$O (and electrical work).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion"},{"id":"che-ek-197","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A buried iron pipeline is protected by attaching blocks of zinc or magnesium because those metals","options":["act as sacrificial anodes and corrode in preference to iron","raise the $E^\\circ$ of iron above that of oxygen","convert iron into stainless steel","absorb all moisture from the soil"],"answer_index":0,"explanation":"Zn and Mg are more active (more negative $E^\\circ$) than Fe, so they oxidise first and the pipeline becomes cathodic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"batteries-corrosion"},{"id":"che-ek-198","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"On a rusting iron surface the anodic half-change is Fe → Fe$^{2+}$ + 2 e$^-$. The matching cathodic process in a neutral water film is","options":["$\\mathrm{O_2 + 2H_2O + 4e^- \\rightarrow 4OH^-}$","$\\mathrm{Fe^{2+} + 2e^- \\rightarrow Fe}$","$\\mathrm{2H_2O \\rightarrow O_2 + 4H^+ + 4e^-}$","$\\mathrm{Zn^{2+} + 2e^- \\rightarrow Zn}$"],"answer_index":0,"explanation":"Dissolved oxygen is reduced to hydroxide. Fe$^{2+}$ and OH$^-$ then form rust (hydrated Fe$_2$O$_3$) after further oxidation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"batteries-corrosion"},{"id":"che-ek-199","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The instantaneous rate of consumption of a reactant A is written","options":["$-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","$+\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","$[\\mathrm{A}] \\times t$","$\\Delta G / \\Delta t$"],"answer_index":0,"explanation":"Concentration of a reactant falls, so the minus sign makes the rate a positive quantity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-200","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate law such as rate $= k[\\mathrm{A}]^x[\\mathrm{B}]^y$ must be established by","options":["experiment (initial rates or isolation methods)","copying the stoichiometric coefficients in every case","the equilibrium constant alone","the molecular mass of the product"],"answer_index":0,"explanation":"Orders $x$ and $y$ equal stoichiometric numbers only for an elementary step, not for an arbitrary overall equation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-201","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate constant $k$ of a given reaction, at fixed temperature, does not depend on","options":["the concentrations of the reactants","the presence of a catalyst (which actually changes $k$)","temperature (which actually changes $k$)","the activation energy (which actually enters $k$)"],"answer_index":0,"explanation":"$k$ is independent of concentration. It does depend on $T$, $E_a$ and catalysis; the wording isolates the concentration independence.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-202","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Dimensions of $k$ for a zero-order reaction (rate in mol L$^{-1}$ s$^{-1}$) are","options":["mol L$^{-1}$ s$^{-1}$","s$^{-1}$","L mol$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k$ when the order is zero, so $k$ carries the same units as the rate itself.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-203","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A second-order rate constant (concentration in mol L$^{-1}$, time in s) has the unit","options":["L mol$^{-1}$ s$^{-1}$","s$^{-1}$","mol L$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Rate $= k[\\mathrm{A}]^2$ (or $k[\\mathrm{A}][\\mathrm{B}]$) forces $k$ to have units (concentration)$^{-1}$ (time)$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-204","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Average rate over a finite interval is computed as","options":["change in concentration divided by the elapsed time","the slope of the tangent at one instant only","the equilibrium constant divided by time","the activation energy divided by $RT$"],"answer_index":0,"explanation":"Average rate $= \\Delta[\\mathrm{ ]}/\\Delta t$. Instantaneous rate is the derivative (tangent slope).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-205","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For $2\\mathrm{N_2O_5} \\to 4\\mathrm{NO_2} + \\mathrm{O_2}$, the rate of appearance of NO$_2$ compared with the rate of disappearance of N$_2$O$_5$ is","options":["twice as large","the same","half as large","four times smaller"],"answer_index":0,"explanation":"Rate of reaction $= -\\tfrac12 \\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = +\\tfrac14 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$, so $-\\mathrm{d}[\\mathrm{N_2O_5}]/\\mathrm{d}t = \\tfrac12 \\mathrm{d}[\\mathrm{NO_2}]/\\mathrm{d}t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-206","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For an elementary bimolecular collision A + B → products, the rate law is expected to be","options":["rate $= k[\\mathrm{A}][\\mathrm{B}]$","rate $= k$ only","rate $= k[\\mathrm{A}]^2[\\mathrm{B}]^2$","rate $= k / [\\mathrm{A}][\\mathrm{B}]$"],"answer_index":0,"explanation":"In an elementary step the molecularity and the order coincide, so each reactant appears to the first power.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-207","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"When a multi-step mechanism has one distinctly slow step, the observed rate law is usually that of the","options":["rate-determining (slow) step, after any pre-equilibria are substituted","fastest step alone, ignoring the slow one","overall stoichiometry in every case","reverse reaction only"],"answer_index":0,"explanation":"The bottleneck step limits the flux. Intermediates in that step are rewritten using faster equilibria if needed.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-208","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Raising the temperature of a typical thermally activated reaction increases $k$ because","options":["a larger fraction of collisions then exceeds the activation barrier","concentrations in the rate law are redefined","the stoichiometric coefficients change","the Faraday constant grows with $T$"],"answer_index":0,"explanation":"Arrhenius behaviour: $k = A e^{-E_a/RT}$ grows rapidly as $T$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-209","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The rate of the reaction $a\\mathrm{A} \\to$ products is defined so that","options":["rate $= -\\tfrac1a \\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= -a\\,\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t$","rate $= +a[\\mathrm{A}]$","rate $= [\\mathrm{A}]^a$ with no $k$"],"answer_index":0,"explanation":"Dividing by the stoichiometric coefficient makes the rate the same whichever species is monitored.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-law"},{"id":"che-ek-210","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If rate $= k[\\mathrm{A}]^2$ and [A] is doubled at constant $T$, the instantaneous rate becomes","options":["four times the original rate","twice the original rate","unchanged","half the original rate"],"answer_index":0,"explanation":"Second order in A: $(2)^2 = 4$, so the rate quadruples.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law"},{"id":"che-ek-211","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A reaction has rate $= 2.0 \\times 10^{-4}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$ when [A] = 0.10 M and is first order in A only. $k$ equals","options":["$2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-4}\\ \\mathrm{L\\ mol^{-1}\\ s^{-1}}$","$0.10\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"$k = \\mathrm{rate}/[\\mathrm{A}] = 2.0 \\times 10^{-4}/0.10 = 2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law"},{"id":"che-ek-212","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For rate $= k[\\mathrm{A}][\\mathrm{B}]$ the unit of $k$ (conc. in mol L$^{-1}$) is","options":["L mol$^{-1}$ s$^{-1}$","s$^{-1}$","mol L$^{-1}$ s$^{-1}$","L$^2$ mol$^{-2}$ s$^{-1}$"],"answer_index":0,"explanation":"Two concentration factors sit with $k$, so $k$ is second-order: L mol$^{-1}$ s$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-law"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-ek-193","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-194","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-195","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-196","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-197","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-198","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-199","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-200","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-201","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-202","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-203","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-204","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-205","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-206","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-207","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-208","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-209","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-210","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-211","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-ek-212","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
